class world_dynamics_system {
public:
    struct surface_type_info;
};

template<class T1, class T2>
struct pair {
    T1 first;
    T2 second;
};

template<class Pair>
struct _Select1st {
    const typename Pair::first_type& operator()(const Pair& value) const {
        return value.first;
    }
};

template<class T>
struct less {
    bool operator()(const T& left, const T& right) const {
        return left < right;
    }
};

template<class T>
struct my_allocator {};

struct _Rb_tree_node_base {
    int color;
    _Rb_tree_node_base *parent;
    _Rb_tree_node_base *left;
    _Rb_tree_node_base *right;
};

template<class Value>
struct _Rb_tree_node : _Rb_tree_node_base {
    Value value_field;
};

extern void *__default_alloc_free_list[16];
extern "C" void *__default_alloc_refill(unsigned int)
    __asm__("_S_refill__t27__my_default_alloc_template2b0i0Ui");
__asm__(".equ __default_alloc_free_list,0x003E5628");
__asm__(".equ _S_refill__t27__my_default_alloc_template2b0i0Ui,0x0010DAE0");

template<class Key, class Value, class KeyOfValue, class Compare, class Alloc>
class _Rb_tree {
    typedef _Rb_tree_node_base *base_ptr;
    typedef _Rb_tree_node<Value> *link_type;

public:
    struct iterator {
        base_ptr node;
        iterator(base_ptr value) : node(value) {}
    };

private:
    link_type header;
    unsigned int node_count;
    Compare key_compare;

    link_type get_node() {
        const unsigned int size = (sizeof(_Rb_tree_node<Value>) + 7) & ~7;
        const unsigned int index = size / 8 - 1;
        void *result = __default_alloc_free_list[index];
        if (result == 0)
            result = __default_alloc_refill(size);
        else
            __default_alloc_free_list[index] = *(void **)result;
        return (link_type)result;
    }

    static const Key& key(link_type value) {
        return value->value_field.first;
    }

public:
    iterator _M_insert(base_ptr x_, base_ptr y_, const Value& value) {
        link_type x = (link_type)x_;
        link_type y = (link_type)y_;
        link_type z;

        if (y == header || x != 0 || key_compare(value.first, key(y))) {
            z = get_node();
            z->value_field = value;
            y->left = z;
            if (y == header) {
                header->parent = z;
                header->right = z;
            } else if (y == header->left)
                header->left = z;
        } else {
            z = get_node();
            z->value_field = value;
            y->right = z;
            if (y == header->right)
                header->right = z;
        }
        z->parent = y;
        z->left = 0;
        z->right = 0;
        z->color = 0;
        x = z;
        while (x != (link_type)header->parent && x->parent->color == 0) {
            if (x->parent == x->parent->parent->left) {
                y = (link_type)x->parent->parent->right;
                if (y && y->color == 0) {
                    x->parent->color = 1;
                    y->color = 1;
                    x->parent->parent->color = 0;
                    x = (link_type)x->parent->parent;
                } else {
                    if (x == x->parent->right) {
                        x = (link_type)x->parent;
                        link_type w = (link_type)x->right;
                        x->right = w->left;
                        if (w->left) w->left->parent = x;
                        w->parent = x->parent;
                        if (x == header->parent) header->parent = w;
                        else if (x == x->parent->left) x->parent->left = w;
                        else x->parent->right = w;
                        w->left = x;
                        x->parent = w;
                    }
                    x->parent->color = 1;
                    x->parent->parent->color = 0;
                    link_type w = (link_type)x->parent->parent;
                    link_type q = (link_type)w->left;
                    w->left = q->right;
                    if (q->right) q->right->parent = w;
                    q->parent = w->parent;
                    if (w == header->parent) header->parent = q;
                    else if (w == w->parent->right) w->parent->right = q;
                    else w->parent->left = q;
                    q->right = w;
                    w->parent = q;
                }
            } else {
                y = (link_type)x->parent->parent->left;
                if (y && y->color == 0) {
                    x->parent->color = 1;
                    y->color = 1;
                    x->parent->parent->color = 0;
                    x = (link_type)x->parent->parent;
                } else {
                    if (x == x->parent->left) {
                        x = (link_type)x->parent;
                        link_type w = (link_type)x->left;
                        x->left = w->right;
                        if (w->right) w->right->parent = x;
                        w->parent = x->parent;
                        if (x == header->parent) header->parent = w;
                        else if (x == x->parent->right) x->parent->right = w;
                        else x->parent->left = w;
                        w->right = x;
                        x->parent = w;
                    }
                    x->parent->color = 1;
                    x->parent->parent->color = 0;
                    link_type w = (link_type)x->parent->parent;
                    link_type q = (link_type)w->right;
                    w->right = q->left;
                    if (q->left) q->left->parent = w;
                    q->parent = w->parent;
                    if (w == header->parent) header->parent = q;
                    else if (w == w->parent->left) w->parent->left = q;
                    else w->parent->right = q;
                    q->left = w;
                    w->parent = q;
                }
            }
        }
        header->parent->color = 1;
        ++node_count;
        return iterator(z);
    }
};

typedef pair<const int, world_dynamics_system::surface_type_info*> value_type;
template class _Rb_tree<int, value_type, _Select1st<value_type>,
                        less<int>,
                        my_allocator<world_dynamics_system::surface_type_info*> >;
